  insert into students (id, school_id, admission_no, full_name, dob, section_id) values (v_student, 'a0000000-0000-0000-0000-000000000001', 'KAL-2026-' || lpad((200 + i)::text, 4, '0'),
    (array['Aarav','Diya','Kabir','Myra','Vihaan','Anika','Reyansh','Saanvi','Arjun','Ira'])[1 + i % 10] || ' ' || (array['Sharma','Verma','Iyer','Nair','Reddy','Gupta','Menon','Rao'])[1 + i % 8],
    date '2014-05-01' + i * 6, 'c0000000-0000-0000-0000-000000000006');
  insert into guardians (id, school_id, full_name, phone, email) values (v_guardian, 'a0000000-0000-0000-0000-000000000001', 'Guardian ' || i, '98' || lpad((200000000 + i)::text, 8, '0'), 'guardian' || (200 + i) || '@example.test');
  insert into student_guardians (student_id, guardian_id, relation, is_primary) values (v_student, v_guardian, 'parent', true);
  insert into consent_records (school_id, student_id, guardian_id, purpose, consent_version, granted, via) select 'a0000000-0000-0000-0000-000000000001', v_student, v_guardian, p, 'v1-2026', true, 'paper' from unnest(array['data_processing','parent_input','report_release','media_use']) p;
end loop; end $$;

-- observations: bring the two Class 6 sections to 380 in total (existing 48 for 6A students 1-8)
insert into observations (school_id, student_id, teacher_id, domain, context, note, observed_on)
select st.school_id, st.id, 'd0000000-0000-0000-0000-000000000001', o.domain, o.context, o.note, current_date - o.d
from (select id, school_id, row_number() over (order by admission_no) rn from students where section_id in ('c0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000006')) st
cross join lateral (select * from (values
  ('cognitive', 'lab', 'Predicted the outcome before the experiment and checked it against the result.', 5),
  ('cognitive', 'class discussion', 'Asked a why-question that moved the whole discussion forward.', 14),
  ('affective', 'presentation', 'Kept going after losing the thread; recovered without prompting.', 23),
  ('socio_emotional', 'group work', 'Made sure the quietest member of the group got to present a point.', 32),
  ('psychomotor', 'sport', 'Improved throwing accuracy across three sessions; still rushes the release.', 41)) as v(domain, context, note, d)) o
where (st.rn > 8 and (o.d < 40 or st.rn > 80)) or (st.rn <= 8 and o.d > 30)
;

-- 360 inputs for every Class 6 student who lacks them
insert into hpc_inputs (school_id, student_id, term, source, submitted_by, submitted_by_student, responses)
select st.school_id, st.id, 'T1 2026-27', 'self', null, st.id, '{"enjoy_most": "Science experiments and art", "proud_of": "Finishing my project on time", "want_to_improve": "Speaking up in class", "help_needed": "Reminders to check my work"}'::jsonb from students st
where st.section_id in ('c0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000006') and not exists (select 1 from hpc_inputs i where i.student_id = st.id and i.term = 'T1 2026-27' and i.source = 'self');
insert into hpc_inputs (school_id, student_id, term, source, submitted_by, submitted_by_student, responses)
select st.school_id, st.id, 'T1 2026-27', 'peer', null, (select p.id from students p where p.section_id = st.section_id and p.id <> st.id order by p.admission_no limit 1), '{"good_at": "Explaining maths steps", "kind_when": "Lent me a pencil and notes", "could_try": "Listening before answering"}'::jsonb from students st
where st.section_id in ('c0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000006') and not exists (select 1 from hpc_inputs i where i.student_id = st.id and i.term = 'T1 2026-27' and i.source = 'peer');
insert into hpc_inputs (school_id, student_id, term, source, submitted_by, submitted_by_student, responses)
select st.school_id, st.id, 'T1 2026-27', 'parent', null, null, '{"at_home": "Draws and reads comics", "interests": "Cricket, cooking", "concerns": "Rushes homework", "support_wanted": "A short daily routine"}'::jsonb from students st
where st.section_id in ('c0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000006') and not exists (select 1 from hpc_inputs i where i.student_id = st.id and i.term = 'T1 2026-27' and i.source = 'parent');
insert into hpc_inputs (school_id, student_id, term, source, submitted_by, submitted_by_student, responses)
select st.school_id, st.id, 'T1 2026-27', 'teacher', 'd0000000-0000-0000-0000-000000000001', null, '{"participation": "Regular", "homework": "On time", "collaboration": "Good", "note": "Responds well to a checklist"}'::jsonb from students st
where st.section_id in ('c0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000006') and not exists (select 1 from hpc_inputs i where i.student_id = st.id and i.term = 'T1 2026-27' and i.source = 'teacher');

-- descriptors: 60 students fully approved (240), 4 students with one unapproved draft each
with ranked as (select id, school_id, row_number() over (order by section_id, admission_no) rn from students where section_id in ('c0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000006'))
insert into hpc_descriptors (id, school_id, student_id, term, domain, generated_text, generated_json, final_text, status, drafted_by)
select uuid_generate_v5('6ba7b810-9dad-11d1-80b4-00c04fd430c8', 'acharya/demo/desc/' || r.id || '/' || d.domain), r.school_id, r.id, 'T1 2026-27', d.domain, d.txt,
  jsonb_build_object('strengths', array[d.txt], 'growth_areas', array['Keep the momentum next term.'], 'next_step', 'Agree one weekly goal with the class teacher.'), d.txt, 'draft', 'd0000000-0000-0000-0000-000000000001'
from ranked r cross join (values ('cognitive', 'Explains ideas using the right terms and checks predictions against results; next term, write the conclusion before discussing it.'), ('affective', 'Shows persistence and curiosity, bringing examples from home; keep noticing what helps when a task feels hard.'), ('socio_emotional', 'Includes quieter classmates and resolves disagreements fairly; next, take a turn as the group''s timekeeper.'), ('psychomotor', 'Controlled, careful work in practical and physical tasks; slow the release when throwing.')) as d(domain, txt)
where r.rn between 5 and 64 or (r.rn between 65 and 68 and d.domain <> 'psychomotor') or (r.rn between 65 and 68 and d.domain = 'psychomotor')
on conflict (student_id, term, domain) do nothing;
with ranked as (select id, row_number() over (order by section_id, admission_no) rn from students where section_id in ('c0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000006'))
insert into approvals (school_id, artifact_type, artifact_id, generated_version, final_version, edit_distance, approved_by, approved_at)
select d.school_id, 'descriptor', d.id, to_jsonb(d.generated_text), to_jsonb(d.final_text), (random() * 30)::int, 'd0000000-0000-0000-0000-000000000001', now() - (random() * interval '20 days')
from hpc_descriptors d join ranked r on r.id = d.student_id
where d.status = 'draft' and (r.rn between 5 and 64 or (r.rn between 65 and 68 and d.domain <> 'psychomotor'))
on conflict (artifact_type, artifact_id) do nothing;
update hpc_descriptors d set status = 'approved', approved_by = 'd0000000-0000-0000-0000-000000000001', approved_at = now() - interval '3 days'
where d.status = 'draft' and exists (select 1 from approvals a where a.artifact_type = 'descriptor' and a.artifact_id = d.id);

-- 180 SAARTHI artifacts (140 approved with edit distances; 3 Hindi)
do $$ declare v uuid; k text; i int; n_existing int; begin
select count(*) into n_existing from artifacts where school_id = 'a0000000-0000-0000-0000-000000000001';
for i in 1..(180 - n_existing) loop
  k := (array['lesson_plan','worksheet','rubric','parent_message','activity','remediation_set','revision_sheet'])[1 + i % 7];
  v := create_artifact(jsonb_build_object('school_id', 'a0000000-0000-0000-0000-000000000001', 'kind', k,
     'title', (case k when 'lesson_plan' then 'Photosynthesis in context' when 'worksheet' then 'Fractions practice' when 'rubric' then 'Lab report rubric' when 'parent_message' then 'A good week in Science' when 'activity' then 'Human food chain' when 'remediation_set' then 'Remediation set: Unit 1' when 'revision_sheet' then 'Unit 1 revision' end) || ' #' || i,
     'body', (case k when 'lesson_plan' then '{"title": "Photosynthesis in context", "objectives": [{"text": "Explain the inputs and outputs of photosynthesis", "outcome_ref": "CBSE.SCI.6.1.1"}, {"text": "Design a fair test on light", "outcome_ref": "CBSE.SCI.6.1.2"}], "hook": "Two identical plants, one in a cupboard for a week.", "sequence": [{"step": "Hook and predictions", "minutes": 8, "teacher_does": "Shows plants", "students_do": "Predict"}, {"step": "Core explanation", "minutes": 12, "teacher_does": "Diagram", "students_do": "Annotate"}, {"step": "Fair test design", "minutes": 15, "teacher_does": "Circulates", "students_do": "Plan in pairs"}, {"step": "Exit check", "minutes": 5, "teacher_does": "Collects", "students_do": "Answer"}], "checks_for_understanding": ["Thumbs poll on inputs", "Exit ticket"], "differentiation": {"support": "Word bank", "core": "Diagram from memory", "extension": "Predict the cupboard plant''s mass"}, "closure": "Revisit predictions", "homework": "Observe a plant at home for 3 days"}'::jsonb when 'worksheet' then '{"title": "Fractions practice", "levels": {"support": {"instructions": "Use the fraction wall.", "questions": [{"q": "1/2 + 1/4", "marks": 1}, {"q": "Shade 3/4", "marks": 1}, {"q": "Which is bigger, 1/3 or 1/4?", "marks": 1}]}, "core": {"instructions": "Show working.", "questions": [{"q": "2/3 + 1/6", "marks": 2}, {"q": "5/8 - 1/4", "marks": 2}, {"q": "Order 2/5, 1/2, 3/10", "marks": 2}]}, "extension": {"instructions": "Explain your reasoning.", "questions": [{"q": "A recipe uses 3/4 cup for 6 people. For 8?", "marks": 3}, {"q": "Prove 1/2 > 3/7", "marks": 3}, {"q": "Two fractions summing to 1 with different denominators", "marks": 3}]}}, "answer_key": [{"level": "support", "answers": ["3/4", "diagram", "1/3"]}]}'::jsonb when 'rubric' then '{"title": "Lab report rubric", "task": "Write up the germination experiment", "criteria": [{"name": "Aim and hypothesis", "outcome_ref": "CBSE.SCI.6.1.1", "bands": [{"level": "Beginning", "descriptor": "Aim stated", "marks": 1}, {"level": "Developing", "descriptor": "Aim and a testable hypothesis", "marks": 2}, {"level": "Proficient", "descriptor": "Hypothesis links to variables", "marks": 3}, {"level": "Exemplary", "descriptor": "Justified with prior knowledge", "marks": 4}]}, {"name": "Method", "bands": [{"level": "Beginning", "descriptor": "Steps listed", "marks": 1}, {"level": "Developing", "descriptor": "Steps in order", "marks": 2}, {"level": "Proficient", "descriptor": "Fair test controls named", "marks": 3}, {"level": "Exemplary", "descriptor": "Repeatable by a peer", "marks": 4}]}, {"name": "Conclusion", "bands": [{"level": "Beginning", "descriptor": "Result stated", "marks": 1}, {"level": "Developing", "descriptor": "Result explained", "marks": 2}, {"level": "Proficient", "descriptor": "Linked to hypothesis", "marks": 3}, {"level": "Exemplary", "descriptor": "Limitations discussed", "marks": 4}]}]}'::jsonb when 'parent_message' then '{"subject": "A good week in Science", "message": "Namaste. This week your child set up the germination tray carefully and explained to the group why the cotton had to stay moist. At home, you could ask them to describe what changed each day. I would be glad to talk at the next parent meeting."}'::jsonb when 'activity' then '{"title": "Human food chain", "duration_minutes": 30, "materials": ["Cards", "String"], "steps": ["Hand out organism cards", "Students link with string", "Remove one organism, discuss"], "assessment_note": "Look for correct arrow direction and reasoning about energy."}'::jsonb when 'remediation_set' then '{"weak_outcomes": [{"ref_code": "CBSE.SCI.10.1.1", "statement": "Recall cell structure", "avg": 0.42, "source": "bank", "items": [{"stem": "Label the parts of a plant cell.", "marks": 2}]}], "bank_first": true, "generated_for": [], "needs_generation": []}'::jsonb when 'revision_sheet' then '{"title": "Unit 1 revision", "sections": [{"outcome_ref": "CBSE.SCI.6.1.1", "key_points": ["Inputs: light, water, CO2", "Outputs: glucose, oxygen"], "common_errors": ["Confusing respiration with photosynthesis"], "practice": ["Name two inputs", "Why is chlorophyll needed?"]}]}'::jsonb end),
     'generated_version', (case k when 'lesson_plan' then '{"title": "Photosynthesis in context", "objectives": [{"text": "Explain the inputs and outputs of photosynthesis", "outcome_ref": "CBSE.SCI.6.1.1"}, {"text": "Design a fair test on light", "outcome_ref": "CBSE.SCI.6.1.2"}], "hook": "Two identical plants, one in a cupboard for a week.", "sequence": [{"step": "Hook and predictions", "minutes": 8, "teacher_does": "Shows plants", "students_do": "Predict"}, {"step": "Core explanation", "minutes": 12, "teacher_does": "Diagram", "students_do": "Annotate"}, {"step": "Fair test design", "minutes": 15, "teacher_does": "Circulates", "students_do": "Plan in pairs"}, {"step": "Exit check", "minutes": 5, "teacher_does": "Collects", "students_do": "Answer"}], "checks_for_understanding": ["Thumbs poll on inputs", "Exit ticket"], "differentiation": {"support": "Word bank", "core": "Diagram from memory", "extension": "Predict the cupboard plant''s mass"}, "closure": "Revisit predictions", "homework": "Observe a plant at home for 3 days"}'::jsonb when 'worksheet' then '{"title": "Fractions practice", "levels": {"support": {"instructions": "Use the fraction wall.", "questions": [{"q": "1/2 + 1/4", "marks": 1}, {"q": "Shade 3/4", "marks": 1}, {"q": "Which is bigger, 1/3 or 1/4?", "marks": 1}]}, "core": {"instructions": "Show working.", "questions": [{"q": "2/3 + 1/6", "marks": 2}, {"q": "5/8 - 1/4", "marks": 2}, {"q": "Order 2/5, 1/2, 3/10", "marks": 2}]}, "extension": {"instructions": "Explain your reasoning.", "questions": [{"q": "A recipe uses 3/4 cup for 6 people. For 8?", "marks": 3}, {"q": "Prove 1/2 > 3/7", "marks": 3}, {"q": "Two fractions summing to 1 with different denominators", "marks": 3}]}}, "answer_key": [{"level": "support", "answers": ["3/4", "diagram", "1/3"]}]}'::jsonb when 'rubric' then '{"title": "Lab report rubric", "task": "Write up the germination experiment", "criteria": [{"name": "Aim and hypothesis", "outcome_ref": "CBSE.SCI.6.1.1", "bands": [{"level": "Beginning", "descriptor": "Aim stated", "marks": 1}, {"level": "Developing", "descriptor": "Aim and a testable hypothesis", "marks": 2}, {"level": "Proficient", "descriptor": "Hypothesis links to variables", "marks": 3}, {"level": "Exemplary", "descriptor": "Justified with prior knowledge", "marks": 4}]}, {"name": "Method", "bands": [{"level": "Beginning", "descriptor": "Steps listed", "marks": 1}, {"level": "Developing", "descriptor": "Steps in order", "marks": 2}, {"level": "Proficient", "descriptor": "Fair test controls named", "marks": 3}, {"level": "Exemplary", "descriptor": "Repeatable by a peer", "marks": 4}]}, {"name": "Conclusion", "bands": [{"level": "Beginning", "descriptor": "Result stated", "marks": 1}, {"level": "Developing", "descriptor": "Result explained", "marks": 2}, {"level": "Proficient", "descriptor": "Linked to hypothesis", "marks": 3}, {"level": "Exemplary", "descriptor": "Limitations discussed", "marks": 4}]}]}'::jsonb when 'parent_message' then '{"subject": "A good week in Science", "message": "Namaste. This week your child set up the germination tray carefully and explained to the group why the cotton had to stay moist. At home, you could ask them to describe what changed each day. I would be glad to talk at the next parent meeting."}'::jsonb when 'activity' then '{"title": "Human food chain", "duration_minutes": 30, "materials": ["Cards", "String"], "steps": ["Hand out organism cards", "Students link with string", "Remove one organism, discuss"], "assessment_note": "Look for correct arrow direction and reasoning about energy."}'::jsonb when 'remediation_set' then '{"weak_outcomes": [{"ref_code": "CBSE.SCI.10.1.1", "statement": "Recall cell structure", "avg": 0.42, "source": "bank", "items": [{"stem": "Label the parts of a plant cell.", "marks": 2}]}], "bank_first": true, "generated_for": [], "needs_generation": []}'::jsonb when 'revision_sheet' then '{"title": "Unit 1 revision", "sections": [{"outcome_ref": "CBSE.SCI.6.1.1", "key_points": ["Inputs: light, water, CO2", "Outputs: glucose, oxygen"], "common_errors": ["Confusing respiration with photosynthesis"], "practice": ["Name two inputs", "Why is chlorophyll needed?"]}]}'::jsonb end),
     'subject_id', 'b0000000-0000-0000-0000-000000000001', 'grade', '6', 'framework_id', (select id from frameworks where code = 'CBSE'), 'section_id', 'c0000000-0000-0000-0000-000000000001',
     'language', case when i <= 3 then 'hi' else 'en' end, 'origin', 'ai_generated', 'created_by', (case when i % 3 = 0 then 'd0000000-0000-0000-0000-000000000001' else 'd0000000-0000-0000-0000-000000000003' end)),
     array[(select id from learning_outcomes where ref_code = 'CBSE.SCI.6.1.1' and school_id = 'a0000000-0000-0000-0000-000000000001')]::uuid[]);
  if i <= 140 then
    insert into approvals (school_id, artifact_type, artifact_id, generated_version, final_version, edit_distance, approved_by, approved_at)
    select a.school_id, 'artifact', a.id, a.generated_version, a.body, (random() * 120)::int, 'd0000000-0000-0000-0000-000000000001', now() - (random() * interval '80 days') from artifacts a where a.id = v;
    update artifacts set status = 'approved', approved_by = 'd0000000-0000-0000-0000-000000000001', approved_at = now() - interval '1 day' where id = v;
    if i % 4 = 0 then insert into artifact_shares (artifact_id, shared_with_role, shared_with_subject, shared_by) values (v, 'teacher', 'b0000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000001'); update artifacts set status = 'shared' where id = v; end if;
  end if;
end loop; end $$;
update artifacts set title = replace(title, 'A good week in Science', 'विज्ञान में एक अच्छा सप्ताह'), body = jsonb_set(body, '{subject}', '"विज्ञान में एक अच्छा सप्ताह"') where language = 'hi' and kind = 'parent_message';

